$$('a[href]').forEach(a=>{if(!a.hasAttribute('data-test-exit'))a.href=href(a.href);});if(screen==='welcome')$('[data-action=language]').textContent=lang==='ru'?'UZ':'RU';
const status=k=>{let p=$('[data-status]');if(!p){p=document.createElement('p');p.className='status';p.setAttribute('role','status');document.querySelector('main').append(p);}p.textContent=t(k);};
