const tb=window.Telegram?.WebApp?.BackButton;if(s.parent){tb?.show();tb?.onClick(backAction);addEventListener('pagehide',()=>tb?.offClick(backAction));}else tb?.hide();
const photoSource=()=>photoSources[photoIndex]||`../../welcome/assets/couple-${photoIndex===0?'male':'female'}.png`;
function paintPhoto(host){const img=host.querySelector('[data-full-photo]');img.src=photoSource();host.querySelector('[data-photo-position]').textContent=t('photoPosition',{current:photoIndex+1,total:photoSources.length||2});}
function openPhoto(trigger){photoSources=trigger?.dataset.photoSrc?$$('[data-photo-src]').map(e=>e.dataset.photoSrc):[];photoIndex=trigger?.dataset.photoSrc?Math.max(0,photoSources.indexOf(trigger.dataset.photoSrc)):0;returnFocus=document.activeElement;modal=document.createElement('dialog');modal.className='photo-modal';modal.setAttribute('aria-label',t('photoView'));modal.innerHTML=BAH20_SCREENS['photo-viewer'].body(t);document.body.append(modal);paintPhoto(modal);modal.addEventListener('cancel',e=>{e.preventDefault();closePhoto();});modal.showModal();modal.querySelector('[data-action=photo-close]').focus();}
