let topic=q.get('topic')||read('topic','dreams'),seen=read('questions',{}),currentQuestion=null;
function question(next=false){const sel=$('[name=topic]');if(sel)topic=sel.value;write('topic',topic);const list=BAH20_PROMPTS.filter(x=>x.topic===topic&&x.angle==='base');if(!list.length)return;let used=seen[topic]||[];let choice=next?list.find(x=>!used.includes(x.id)):list.find(x=>x.id===read('current-question',null));if(!choice){if(next&&used.length>=list.length)used=[];choice=list.find(x=>!used.includes(x.id))||list[0];}if(!used.includes(choice.id))used.push(choice.id);seen[topic]=used;currentQuestion=choice;write('questions',seen);write('current-question',choice.id);if($('[data-question]'))$('[data-question]').textContent=choice[lang];followup();}
function followup(){const angle=$('[name=angle]')?.value||'detail';const card=BAH20_PROMPTS.find(x=>x.parent===currentQuestion?.id&&x.angle===angle);if($('[data-followup]')&&card)$('[data-followup]').textContent=card[lang];}
