if(screen==='life-ai-review'&&!original)$('[type=submit]').disabled=true;
$$('[data-story-preview]').forEach(e=>{e.textContent=read('story','')||t('demoStory');});if(screen==='life-preview'&&!read('story',''))$('[data-action=life-publish]').disabled=true;
