if(act==='photo-open')return openPhoto(el);if(act==='photo-close'){if(modal)return closePhoto();return go(s.parent||'photo');}if(act==='photo-next'||act==='photo-prev'){photoIndex=(photoIndex+(act==='photo-next'?1:-1)+(photoSources.length||2))%(photoSources.length||2);paintPhoto(modal||document);return;}
if(act==='life-publish'){if(!read('story','').trim())return status('lifeEmpty');write('published',read('story',''));go('life-published');return;}if(act==='life-remove'){write('published','');status('lifeUnpublished');return;}
